import{_ as t,o,c as r,a2 as a}from"./chunks/framework.G0y0PQA7.js";const n="/relio/shots/en/git-compare-pane.png",i="/relio/shots/en/git-merge-pane.png",u=JSON.parse('{"title":"Git and merging","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/git.md","filePath":"en/features/git.md"}'),s={name:"en/features/git.md"};function d(l,e,h,g,c,m){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="git-and-merging" tabindex="-1">Git and merging <a class="header-anchor" href="#git-and-merging" aria-label="Permalink to &quot;Git and merging&quot;">​</a></h1><p>Comparing two models and migration SQL, the Git history panel, model-level merging (three-way merge) and the Git merge driver.</p><p>To follow along from preparing the repository, see <a href="/relio/en/quick/git">Work together and merge with Git</a> in Quick start. None of these features ever write anything to your Git repository.</p><h2 id="preparing-the-repository" tabindex="-1">Preparing the repository <a class="header-anchor" href="#preparing-the-repository" aria-label="Permalink to &quot;Preparing the repository&quot;">​</a></h2><p>Sorted saving, which keeps Git diffs small (on by default), is described in <a href="/relio/en/features/file#sorted-saving">File › Sorted saving</a>. Add one line to the repository&#39;s <code>.gitattributes</code> to keep line endings consistent:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*.erm text eol=lf merge=relio</span></span></code></pre></div><h2 id="compare-and-merge-menu" tabindex="-1">Compare and merge menu <a class="header-anchor" href="#compare-and-merge-menu" aria-label="Permalink to &quot;Compare and merge menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Menu › Item</th><th>What it does</th></tr></thead><tbody><tr><td>File › Compare and merge › Compare two files…</td><td>Pick file A (before) and B (after) and compare them.</td></tr><tr><td>File › Compare and merge › Compare with saved file</td><td>Compares the current document&#39;s unsaved changes with the file on disk.</td></tr><tr><td>File › Compare and merge › Compare with another file…</td><td>Compares a file you pick (A) with the open document (B).</td></tr><tr><td>File › Compare and merge › Resolve Git merge conflict…</td><td>Resolves a file in a Git merge conflict at the model level.</td></tr><tr><td>File › Compare and merge › Merge with another branch version…</td><td>Merges with the same file on another branch.</td></tr><tr><td>File › Git history</td><td>Opens the Git history panel for this file. You can also click the branch name in the status bar.</td></tr></tbody></table><h2 id="comparison-view" tabindex="-1">Comparison view <a class="header-anchor" href="#comparison-view" aria-label="Permalink to &quot;Comparison view&quot;">​</a></h2><p>A comparison opens in a read-only tab. Tables, columns and relationships are paired by name and internal number, and renames are guessed from similarity.</p><ul><li><strong>Change list</strong> — Shows Added · Removed · Changed · Renamed · Moved · Property change. Expand an item to see the <strong>Before</strong> · <strong>After</strong> value of each field. Items paired by guessing are marked &quot;(guessed)&quot;.</li><li><strong>Group: By table / By type</strong> — Groups the change list per table or per kind of change (<kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>G</kbd>). Markdown export and copy follow this grouping.</li><li><strong>Filters</strong> — Choose which changes to show (Structure · Documentation · Layout · Settings), and filter with <strong>Search names</strong> and <strong>Guesses only</strong> (only renames guessed from similarity).</li><li><strong>Side shown on the canvas</strong> — <strong>Show A</strong> · <strong>Show B</strong>. Turn on <strong>Dim the rest</strong> to draw unchanged objects dimmed.</li><li><strong>Swap A⇄B</strong> reverses the direction, and <strong>Compare again</strong> reloads both sides.</li><li><strong>Open A</strong> · <strong>Open B</strong> — Open the original file to edit it.</li><li><strong>Export ▾</strong> — <strong>Markdown…</strong> · <strong>CSV…</strong> · <strong>JSON…</strong> (everything, regardless of filters) · <strong>Copy (Markdown)</strong> · <strong>Generate migration SQL…</strong>. Markdown and CSV follow the current filters.</li><li>If the two models are identical, it says &quot;The two models are the same&quot;.</li></ul><h3 id="change-marks-on-the-canvas" tabindex="-1">Change marks on the canvas <a class="header-anchor" href="#change-marks-on-the-canvas" aria-label="Permalink to &quot;Change marks on the canvas&quot;">​</a></h3><ul><li>Changed nodes are marked with a border color and a circle at the top left (<code>+</code> added · <code>−</code> removed · <code>~</code> changed); changed columns with a background color on their line and a symbol at the end.</li><li>In <strong>Show B</strong>, removed tables, views, notes and images appear at their old position in A as gray dashed boxes (<code>− name</code>, struck through), and removed columns as dashed lines under their table (<code>− column name</code>, struck through).</li><li>In <strong>Show A</strong> it is the other way round: what was added in B appears as dashed boxes and lines (<code>+ name</code>).</li><li>Click a dashed box or line to select that item in the change list.</li></ul><h3 id="change-list-keys" tabindex="-1">Change list keys <a class="header-anchor" href="#change-list-keys" aria-label="Permalink to &quot;Change list keys&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><kbd>↑</kbd> <kbd>↓</kbd></td><td>Move between items</td></tr><tr><td><kbd>→</kbd> / <kbd>←</kbd></td><td>Expand / collapse the selected item</td></tr><tr><td><kbd>Enter</kbd></td><td>Shows the selected item on the canvas.</td></tr><tr><td><kbd>Ctrl</kbd>+<kbd>C</kbd></td><td>Copies the selected change as Markdown</td></tr></tbody></table><figure class="shot" data-scene="git-compare-pane"><img src="'+n+'" alt="Comparison view — the change list grouped by table, with side B on the canvas" loading="lazy"><figcaption>Comparison view — the change list grouped by table, with side B on the canvas</figcaption></figure><h2 id="generating-migration-sql" tabindex="-1">Generating migration SQL <a class="header-anchor" href="#generating-migration-sql" aria-label="Permalink to &quot;Generating migration SQL&quot;">​</a></h2><p>Export ▾ › <strong>Generate migration SQL…</strong> in the comparison view generates SQL (ALTER and so on) that changes a database with A&#39;s structure into B&#39;s structure. PostgreSQL · MySQL · MariaDB · SQL Server · Oracle are supported. Relio only generates this SQL; it never runs it.</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Target database · Target product · Target version</td><td>The database to generate the SQL for.</td></tr><tr><td>Swap direction</td><td>Swaps A and B to generate SQL in the opposite direction.</td></tr><tr><td>n renames guessed</td><td>How to write renames that are not certain: <strong>Keep as comments</strong> (default) · <strong>Rename</strong> · <strong>Drop and add</strong></td></tr><tr><td>Include database comments</td><td>Also generates SQL for comment changes.</td></tr><tr><td>Wrap in one transaction</td><td>Wraps the whole script in a single transaction (on databases that support it).</td></tr><tr><td>File name</td><td><strong>Default name</strong> or <strong>Flyway name</strong></td></tr></tbody></table><ul><li>The <strong>SQL</strong> tab shows the script and the <strong>Warnings</strong> tab shows risky changes. Risky changes are flagged as <strong>Data loss</strong> (data disappears) · <strong>Data-dependent</strong> (may fail depending on the data) · <strong>Breaking change</strong> (outside programs may break).</li><li>With &quot;Keep as comments&quot;, uncertain spots are written as comments and Relio tells you how many items need review — until you decide, the result differs from B.</li><li>Changes that cannot be generated are listed in a &quot;Manual step required&quot; list at the end of the script.</li><li>Export with <strong>Save…</strong> · <strong>Copy</strong>. On the command line, use <code>relio diff --format sql</code>.</li></ul><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Always read migration SQL before running it, deal with the &quot;Manual step required&quot; list, and then run it yourself in your database tool. Back up production databases first.</p></div><h2 id="git-history" tabindex="-1">Git history <a class="header-anchor" href="#git-history" aria-label="Permalink to &quot;Git history&quot;">​</a></h2><p>File › Git history (or the branch name in the status bar) opens a panel on the right.</p><ul><li>At the top, choose the current branch or another branch or tag in <strong>Branch or tag to start the history from</strong>. <strong>Refresh</strong> reloads it.</li><li><strong>Latest commit card</strong> — Shows a summary of the change from the previous version (<code>Tables +1 · Columns +2 ~3</code>). Click the card to compare with the previous version, or click a chip to open the comparison with that type expanded. Merge commits are compared with their first parent.</li><li>Buttons below the commit list: <ul><li><strong>Compare with previous version</strong> — A = the version just before, B = the selected version.</li><li><strong>Compare with current version</strong> — A = the selected version, B = the open document. Double-clicking a row does the same.</li><li><strong>Compare two versions</strong> — Hold <kbd>Ctrl</kbd> and select two rows (the older one is A).</li><li><strong>Open this version</strong> — Opens that version in a read-only tab (Save as still works).</li></ul></li><li>History follows file renames. For files outside a repository, unsaved documents and read-only tabs, Relio tells you there is no history.</li></ul><h2 id="merging" tabindex="-1">Merging <a class="header-anchor" href="#merging" aria-label="Permalink to &quot;Merging&quot;">​</a></h2><p>When the same <code>.erm</code> was changed in two places, Relio merges by model object (tables, columns, relationships and their fields), not by line. What each side added merges without conflicts; you only choose where the same field was changed differently. The result is always a valid <code>.erm</code>.</p><h3 id="ways-to-open-it" tabindex="-1">Ways to open it <a class="header-anchor" href="#ways-to-open-it" aria-label="Permalink to &quot;Ways to open it&quot;">​</a></h3><ul><li><strong>When the file changed outside Relio</strong> — <strong>Merge…</strong> in the notice shown when you return to the window, or in the check just before saving.</li><li><strong>Git merge conflict</strong> — File › Compare and merge › Resolve Git merge conflict…. If you try to open a file that still has conflict markers (<code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</code>), you can resolve it right from the notice. When you open a file in a conflicted state, a &quot;Git merge conflict remains&quot; bar with a <strong>Resolve</strong> button appears at the top.</li><li><strong>With another branch</strong> — Choose the version to merge in File › Compare and merge › Merge with another branch version…. The repository is not changed; only the open document is.</li><li><strong>A file damaged by a line-based merge</strong> — <strong>Redo the merge at the model level</strong> on the &quot;This file may have been damaged by a line-based merge&quot; bar.</li></ul><h3 id="merge-tab" tabindex="-1">Merge tab <a class="header-anchor" href="#merge-tab" aria-label="Permalink to &quot;Merge tab&quot;">​</a></h3><ul><li>The list is split into <strong>Conflicts</strong> · <strong>To review</strong> · <strong>Automatic</strong> (Automatic — current only · Automatic — incoming only · Automatic — same on both). The top shows n automatic · n conflicts (n left) · n to review.</li><li>Expand an item to see the <strong>Base</strong> · <strong>Current</strong> · <strong>Incoming</strong> value of each field, and choose per row.</li><li><strong>Side shown on the canvas</strong> — Result · Current · Incoming. Conflicting objects are highlighted, and <strong>Dim the rest</strong> dims unrelated objects.</li><li>Filter with <strong>Search names</strong> and <strong>Conflicts only</strong>, and decide everything at once with <strong>Current for all remaining conflicts</strong> · <strong>Incoming for all remaining conflicts</strong>. <strong>Copy list</strong> copies the item list as Markdown.</li><li>If the document or the file on disk changes again in the meantime, Relio tells you and suggests <strong>Merge again</strong>.</li></ul><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><kbd>↑</kbd> <kbd>↓</kbd></td><td>Move between items</td></tr><tr><td><kbd>1</kbd> · <kbd>2</kbd> · <kbd>3</kbd></td><td>Current value · incoming value · both</td></tr><tr><td><kbd>F8</kbd> / <kbd>Shift</kbd>+<kbd>F8</kbd></td><td>Next · previous conflict</td></tr><tr><td><kbd>Ctrl</kbd>+<kbd>Enter</kbd></td><td>Apply</td></tr></tbody></table><figure class="shot" data-scene="git-merge-pane"><img src="'+i+'" alt="Merge tab — a conflict expanded to choose between the base, current and incoming values" loading="lazy"><figcaption>Merge tab — a conflict expanded to choose between the base, current and incoming values</figcaption></figure><h3 id="applying" tabindex="-1">Applying <a class="header-anchor" href="#applying" aria-label="Permalink to &quot;Applying&quot;">​</a></h3><p>When no conflicts remain, <strong>Apply</strong> puts the result into the document. The whole merge is undone with a single undo (<kbd>Ctrl</kbd>+<kbd>Z</kbd>). Save to write it to the file. <strong>Cancel</strong> closes the tab without merging (the document is unchanged).</p><p>After you resolve a Git conflict and save, the status bar says &quot;Conflict resolved — run git add … to tell Git&quot;. Run <code>git add</code> yourself.</p><h2 id="git-merge-driver" tabindex="-1">Git merge driver <a class="header-anchor" href="#git-merge-driver" aria-label="Permalink to &quot;Git merge driver&quot;">​</a></h2><p>Register the command-line <code>relio merge</code> as a Git merge driver, and <code>git merge</code> and <code>git rebase</code> merge <code>.erm</code> files at the model level automatically. When conflicts remain, Git leaves the file conflicted; open it in Relio and finish with Resolve Git merge conflict…. How to register and check the driver is in <a href="/relio/en/features/cli#git-merge-driver">Command line › Git merge driver</a>.</p>',37)])])}const b=t(s,[["render",d]]);export{u as __pageData,b as default};
